uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float tracking;
uniform float chroma;
half4 effectMain(float2 coord){float band=fract(coord.y/size.y+(phase*0.0174532925)*0.04);float wobble=sin(coord.y*0.08+(phase*0.0174532925)*3.0)*tracking*size.x;half4 c=image.eval(float2(coord.x+wobble,coord.y));half4 r=image.eval(coord+float2(chroma,0));half4 b=image.eval(coord-float2(chroma,0));half3 rgb=half3(r.r,c.g,b.b);float scan=0.94+0.06*sin(coord.y*1.7);return half4(mix(c.rgb,rgb,half(amount))*half(scan),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
